/**
 * The glossary as one searchable list. Pure functions, no React.
 *
 * WHERE EACH PART COMES FROM, so nothing is written twice:
 *   - shorthands, compounds, name parts, pKa drawings, the substituent rings
 *     and the owner's reference lines: GLOSSARY_DATA, generated by
 *     scripts/glossary.py with RDKit;
 *   - the curriculum's reaction rows: REACTIONS from @blueberry/curriculum,
 *     filed here by functional group through FAMILY_OF_CLASS;
 *   - the pKa NUMBERS: settings/pka.ts, so the page shows the student's own
 *     table (course worksheet or textbook), the same number a lesson grades.
 *
 * Every entry becomes a GlossaryEntry with a lower case `search` string, and
 * the page filters that list with `filterEntries`. The list is built once per
 * pKa settings change, which is cheap: a few hundred rows.
 */
import { REACTIONS, type ChemicalClass, type Reaction } from "@blueberry/curriculum";

import { resolvedLadder, type PkaSettingsSnapshot, type ResolvedPka } from "../settings/pka";
import { GLOSSARY_DATA } from "./glossary.generated";
import type {
  FamilyId,
  GlossaryCompound,
  GlossaryOrigin,
  GlossaryPart,
  GlossaryPkaExample,
  GlossaryReferenceLine,
  GlossaryShorthand,
  GlossarySubstituent,
  PersonalDefinition,
} from "./types";

