  "benzylic halide": "haloalkanes",
  "aryl halide": "aromatics",
  "vicinal dihalide": "haloalkanes",
  "primary alcohol": "alcohols",
  "secondary alcohol": "alcohols",
  "tertiary alcohol": "alcohols",
  "vicinal diol": "alcohols",
  alkoxide: "alcohols",
